  function saveRoutine(s,d) { return transaction(s,w=>{const old=d.id?find(w,'routines',d.id):null,r=routine({...(old||{}),...d,id:old?old.id:uid('routine')},true);if(old)w.routines[w.routines.indexOf(old)]=r;else w.routines.push(r);return r;}); }
  function deleteRoutine(s,k) { return transaction(s,w=>{const r=find(w,'routines',k);w.routines.splice(w.routines.indexOf(r),1);w.routineLog=w.routineLog.filter(x=>x.id!==k);return r;}); }
