    const brought=sum(lines.map(l=>l.brought)),pieceCost=q.ingredientCost===null||!brought?null:(q.ingredientCost+q.packagingCost)/brought;
    if(!closed)return {closed,lines,brought,sold:null,leftover:null,takings:null,stallFee:o.market.stallFee,ingredientCost:q.ingredientCost,packagingCost:q.packagingCost,pieceCost,kept:null,sellThrough:null,lostValue:null,byFate:null};
    const sold=sum(lines.map(l=>l.sold)),leftover=brought-sold,takings=sum(lines.map(l=>l.sold*l.unitPrice+l.reducedTakings)),byFate=Object.fromEntries(fates.map(f=>[f,sum(lines.filter(l=>l.fate===f).map(l=>l.leftover))]));
